@pytest.mark.parametrize('scrollbar_extent', [16, 30]) def test_short_body_keeps_both_panel_actions_inside_its_viewport(qtbot, qapp, tmp_path, scrollbar_extent): """Native scrollbar hints must not stretch every panel past a short body.""" from PyQt5.QtCore import QSettings old_style = qapp.styleSheet() qapp.setStyleSheet(old_style + f' QScrollBar:horizontal {{height: {scrollbar_extent}px;}}' + f' QScrollBar:vertical {{width: {scrollbar_extent}px;}}') try: window = MainWindow(settings=QSettings(str(tmp_path / 'short.ini'), QSettings.IniFormat), db_path=tmp_path / 'short.db', builtin_model_path=tmp_path / 'missing.pth') qtbot.addWidget(window) window.resize(478, 307) # Reproduce the actual native failure's body height independently of # platform title-bar/font metrics. With 30px bars the viewport is 120px. window.body_scroll.setFixedHeight(150) window.show() qtbot.waitExposed(window) qtbot.wait(40) viewport = window.body_scroll.viewport() assert viewport.height() == 150 - scrollbar_extent for mode in ('tiled_analysis', 'single_image'): window.inference_panel.set_classification_mode(mode) qtbot.wait(10) > assert window.splitter.height() == viewport.height() E assert 132 == 120 E + where 132 = <built-in method height of QSplitter object at 0x0000024714346200>() E + where <built-in method height of QSplitter object at 0x0000024714346200> = <PyQt5.QtWidgets.QSplitter object at 0x0000024714346200>.height E + where <PyQt5.QtWidgets.QSplitter object at 0x0000024714346200> = <ui.main_window.MainWindow object at 0x000002471408EC20>.splitter E + and 120 = <built-in method height of QWidget object at 0x00000247143C00D0>() E + where <built-in method height of QWidget object at 0x00000247143C00D0> = <PyQt5.QtWidgets.QWidget object at 0x00000247143C00D0>.height
